% =========================================================================
% 專題名稱：車內乘客呼吸心跳偵測與數位孿生系統 (Phase 2: 動態微動疊加)
% =========================================================================

% 1. 定義雷達硬體與 FMCW 訊號參數
fc = 60e9;             % 操作頻率 60 GHz
bw = 4e9;              % 掃頻帶寬 4 GHz
sweepTime = 1e-3;      % 每次掃描時間 1 毫秒
fs = 2e6;          % 取樣頻率 8 GHz
c = 3e8;               
slope = bw / sweepTime;

waveform = phased.FMCWWaveform('SampleRate', fs, 'SweepTime', sweepTime, 'SweepBandwidth', bw);
txSig = waveform();    % 預先產生發射波形

channel = phased.FreeSpace('OperatingFrequency', fc, 'TwoWayPropagation', true, 'SampleRate', fs);
target = phased.RadarTarget('MeanRCS', 1, 'OperatingFrequency', fc);

% 2. 定義觀測時間與生理參數 (10秒觀測，每秒打 100 次雷達波)
fps = 100;             % 雷達掃描幀率 (Frames Per Second)
duration = 10;         % 總觀測時間 10 秒
numChirps = fps * duration; 
timeVec = (0:numChirps-1) / fps;

Ar = 0.005;  fr = 0.3; % 呼吸：振幅 5mm, 頻率 0.3Hz
Ah = 0.0005; fh = 1.2; % 心跳：振幅 0.5mm, 頻率 1.2Hz

% 準備一個空的二維矩陣來儲存所有雷達訊號 (Data Cube)
beatMatrix = zeros(length(txSig), numChirps);

% 3. 慢時間迴圈 (Slow-Time Loop)：雷達連續觀測
disp('開始執行雷達連續掃描模擬 (約需十幾秒)...'); %[output:6b317834]
for i = 1:numChirps
    % 計算乘客當下的瞬間微動位移
    displacement = Ar * sin(2*pi*fr*timeVec(i)) + Ah * sin(2*pi*fh*timeVec(i));
    current_pos = [0.8 + displacement; 0; 0]; % 基礎距離 0.8m + 微動

    % 發射、傳遞、接收與混頻
    propSig = channel(txSig, [0;0;0], current_pos, [0;0;0], [0;0;0]);
    rxSig = target(propSig);
    beatMatrix(:, i) = dechirp(rxSig, txSig); % 將這次的拍頻訊號存入矩陣
end
disp('模擬完成！開始進行訊號處理...'); %[output:81b7ab52]

% 4. 數位訊號處理 (DSP)：距離-慢時間 FFT 與相位萃取
L = size(beatMatrix, 1);
% 對矩陣的每一個 Column 執行 FFT (Range FFT)
rangeFFT_matrix = fft(beatMatrix, [], 1); 

% 建立距離軸
f_axis = fs * (0:floor(L/2)) / L; 
range_grid = (f_axis * c) / (2 * slope);

% 找出能量最強的距離點 (也就是乘客所在的 0.8m 處)
mean_range_profile = mean(abs(rangeFFT_matrix(1:floor(L/2)+1, :)), 2);
[~, target_idx] = max(mean_range_profile);

% 萃取該距離點在 10 秒內的相位變化 (Phase Extraction)
% 使用 angle() 取出相位，並用 unwrap() 修正相位折疊問題
extracted_phase = unwrap(angle(rangeFFT_matrix(target_idx, :)));

% 移除初始常數相位，只保留變動量
extracted_phase = extracted_phase - mean(extracted_phase);

% 5. 繪製最終還原的生理訊號
figure; %[output:1c0b04f4]
plot(timeVec, extracted_phase, 'LineWidth', 1.5); %[output:1c0b04f4]
xlabel('Time (s)'); %[output:1c0b04f4]
ylabel('Phase Variation (radians)'); %[output:1c0b04f4]
title('Digital Twin: Extracted Vital Sign Phase from FMCW Radar'); %[output:1c0b04f4]
grid on; %[output:1c0b04f4]

